ST.xhtml:p:
NCReset(
     AXIS := NCAxisName^(*AXIS_REF*),
     OUTAXIS =>NCAxisName^ (*AXIS_REF*));
NCReset1(
	AXIS := Axis_C(*AXIS_REF*),
     OUTAXIS =>Axis_C(*AXIS_REF*));
bAxisErrorAlarm :=  NCAxisName^.NCTOPLC.POWERPOSWARN OR NCAxisName^.NCTOPLC.POWERNEGWARN 
     OR NCAxisName^.NCTOPLC.ERRORCODE <>0;


ERRORID := NCReset.ERRORID;
IF bAxisErrorAlarm AND g_bPlcResetBuffer THEN
  NCReset.Execute := TRUE;
ELSE
  NCReset.Execute := FALSE;   
END_IF;

IF Axis_C.NCTOPLC.ERRORCODE <> 0 AND g_bPlcResetBuffer THEN
  NCReset1.EXECUTE := TRUE;
ELSE
  NCReset1.EXECUTE := FALSE;
END_IF;
